//! Writes `content/areas.toml`, Kalimdor's areas from the client's `AreaTable.dbc`: each zone and
//! subzone a character can discover, with its explore bit (`PLAYER_EXPLORED_ZONES`) and name.
//!
//! ```text
//! cargo run -p twilight-realm --example gen_areas -- --data C:/path/to/WoW/Data
//! ```

use std::fmt::Write as _;
use std::path::PathBuf;

use benilla_formats::{load_area_table_catalog, open_chain};

/// `Map.dbc`'s Kalimdor.
const KALIMDOR: u32 = 1;

const HEADER: &str = "\
# Kalimdor's areas, from the client's AreaTable.dbc (map 1), generated by
# `cargo run -p twilight-realm --example gen_areas -- --data <WoW/Data>`.
# `id` is the AreaTable id the host's `area_at` answers, `zone` its parent (0 for a zone),
# `bit` its explore bit in PLAYER_EXPLORED_ZONES. Discovering an area sets its bit.
";

fn main() {
    let data = data_dir();
    let mut chain = open_chain(&data).unwrap_or_else(|e| panic!("{}: {e:#}", data.display()));
    let catalog = load_area_table_catalog(&mut chain).expect("AreaTable.dbc loads");
    let mut rows: Vec<_> = catalog
        .entries()
        .filter(|(_, r)| r.map_id == KALIMDOR)
        .collect();
    rows.sort_by_key(|(id, _)| *id);

    let mut out = String::from(HEADER);
    out.push_str("\narea = [\n");
    for (id, r) in rows {
        let _ = writeln!(
            out,
            "  {{ id = {id}, zone = {}, bit = {}, name = {:?} }},",
            r.zone_id, r.explore_flag, r.name
        );
    }
    out.push_str("]\n");
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("content/areas.toml");
    std::fs::write(&path, out).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    println!("wrote {}", path.display());
}

/// `--data <dir>`, else `WOW_DATA`.
fn data_dir() -> PathBuf {
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        if arg == "--data" {
            return args.next().expect("--data takes a directory").into();
        }
    }
    std::env::var_os("WOW_DATA")
        .map(PathBuf::from)
        .expect("pass --data <WoW/Data> or set WOW_DATA")
}
